"""Offline source levels, original roof pixels and rotatable partial mesh review."""
import argparse
import base64
import gzip
import json
from pathlib import Path
import pymupdf
from PIL import Image
from voxel_mapper.generation_cycles import file_hash
from voxel_mapper.drawing_page_tools import native_inverse


def render(evidence, references, objs, additional_pdfs, output):
    evidence,references,objs,additional_pdfs,output=map(Path,(evidence,references,objs,additional_pdfs,output))
    path=evidence/'preshow-level-geometry.json'; raw=path.read_bytes(); result=json.loads(raw)
    if result['status']!='conditional_preshow_level_geometry_only':raise ValueError('Complete source geometry required')
    if file_hash(references/'roof-reference-evidence.json')!=result['contract']['source_reference_sha256']:raise ValueError('Original reference review changed')
    parent=json.loads((references/'roof-reference-evidence.json').read_text())
    for name,pin in parent['output_artifact_sha256'].items():
        if file_hash(references/name)!=pin:raise ValueError('Original source crop changed')
    manifest=json.loads((objs/'manifest.json').read_text())
    if manifest['source_review_sha256']!=file_hash(path):raise ValueError('Matching OBJ source review required')
    payload={'review_sha256':file_hash(path),'gzip_json':base64.b64encode(gzip.compress(raw,mtime=0)).decode(),
        'images':{},'source_views':{},'obj_files':{},'obj_manifest':manifest}
    for record in parent['rendered_views']:
        receipt=json.loads((references/record['receipt']).read_text());png=references/record['png']
        with Image.open(png) as im:size=list(im.size)
        payload['images'][record['view_id']]={'png':'data:image/png;base64,'+base64.b64encode(png.read_bytes()).decode(),
            'size':size,'sha256':file_hash(png),'caption':record['caption']}
    for page in parent['additional_pages']:
        for target in page['targets']:
            payload['source_views'][json.dumps(target['view_key_candidate'],separators=(',',':'))]={'view_id':target['view_id']}
    for entry in manifest['models']:
        p=objs/entry['file']
        if file_hash(p)!=entry['sha256']:raise ValueError('Original OBJ export changed')
        payload['obj_files'][entry['model_id']]=base64.b64encode(p.read_bytes()).decode()
    html=r'''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Preshow level and roof patches</title>
<style>body{margin:0;background:#eef3f5;color:#193644;font:16px system-ui}main{max-width:1400px;padding:28px;margin:auto}h1{font-size:32px}h2{font-size:20px}p{line-height:1.5}.small{font-size:13px;color:#536f7c}.notice{background:#fff0cb;border-left:4px solid #b17a10;padding:16px}.metrics,.panels{display:grid;gap:18px;margin:22px 0}.metrics{grid-template-columns:repeat(4,1fr)}.panels{grid-template-columns:1fr 1fr}.metric,article{background:white;padding:18px;border:1px solid #d4e0e5;border-radius:8px}.metric b{display:block;font-size:28px}.controls{display:flex;gap:16px;flex-wrap:wrap}label{font-size:14px}select,button{display:block;font:inherit;padding:8px;margin:6px 0;max-width:100%;background:white;border:1px solid #92a9b5;border-radius:4px}button{background:#164b62;color:white;cursor:pointer}button:disabled{opacity:.4;cursor:default}svg{width:100%;height:410px}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:8px;border-bottom:1px solid #dce5e9;text-align:left}pre{white-space:pre-wrap;font-size:12px}details{margin:20px 0}summary{cursor:pointer;font-weight:600;padding:12px}@media(max-width:850px){.panels,.metrics{grid-template-columns:1fr}main{padding:16px}}</style>
<main><div class="small">VOXEL MAPPER / SOURCE-RELATIVE PROTOTYPE GEOMETRY</div><h1>Preshow levels & partial roof patches</h1><p>Separate original level-label fragments now bind to their own native markers. The west source's ridge and fascia-end evidence supports conditional roof patches bounded by original plan caps.</p><p class="notice">These are unplaced source-cap patches. Physical roof/fascia roles, a common datum between sheets and continuous planes remain assumptions. Original 0.504 m rail tails are unmeshed. No complete wing, wall assembly, accepted component, world block or training label is produced.</p><div class="metrics" id="metrics"></div>
<div class="controls"><label>Printed source level<select id="level"></select></label><label>Original gable alternative<select id="pair"></select></label><label>Conditional patch<select id="model"></select></label></div><div class="controls"><label><input type="checkbox" id="full"> Full original source crop</label><label><input type="checkbox" id="pixels" checked> Original fit/check and fascia pixels</label><label>Patch rotation<input type="range" id="yaw" min="-180" max="180" value="135"></label><button id="obj">Download selected OBJ</button><button id="download">Export full evidence JSON</button></div><p id="status"></p>
<div class="panels"><article><h2 id="caption">Original source elevation</h2><svg id="source"></svg><p class="small">Gold/blue: original slope fit spans; dots: even-column fit and odd-column checks. Magenta: whole literal fascia-end column runs. Green: original level marker/leader and separate glyph bounds. Fitted ridges and role assignments remain hypotheses.</p></article><article><h2>Conditional source-cap patch · rotate to inspect</h2><svg id="mesh"></svg><p id="mesh-status" class="small"></p><p id="heights"></p></article></div>
<article><h2>All printed-level differences</h2><table><thead><tr><th>Source view</th><th>Printed difference</th><th>Nominal drawing difference</th><th>Residual</th><th>Result</th></tr></thead><tbody id="levels"></tbody></table></article>
<details><summary>Selected source-marker and fragment receipts</summary><pre id="marker"></pre></details><details><summary>All retained inter-sheet ridge comparisons for this source gable</summary><p class="small">Printed level values are assumed to share a datum for this diagnostic. These are shared project drawings, not independent survey controls. Higher and shifted source gables remain in the review.</p><div id="height-checks"></div></details><details><summary>All source fascia/endcap checks for this gable</summary><pre id="ends"></pre></details><details><summary>Cross-threshold patch comparisons</summary><pre id="thresholds"></pre></details><p class="small" id="hash"></p></main>
<script type="application/json" id="data">PAYLOAD</script><script>
const packed=JSON.parse(document.getElementById('data').textContent),byId=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';let data,raw,state;
function option(e,value,label){let o=document.createElement('option');o.value=value;o.textContent=label;e.append(o)}function node(tag,attrs,parent){let e=document.createElementNS(ns,tag);for(let[k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e}function save(bytes,name,type){let url=URL.createObjectURL(new Blob([bytes],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function current(){let binding=data.bindings.find(b=>b.id===byId('level').value),source=packed.source_views[JSON.stringify(binding.view_key_candidate)],view=data.evidence.gable_views.find(v=>v.view_id===source.view_id),pair=view?.variants.flatMap(s=>s.gable_intersections).find(p=>p.id===byId('pair').value),scan=pair&&view.variants.find(s=>s.gable_intersections.some(p=>p.id===pair.id)),model=data.evidence.conditional_roof_patches.find(m=>m.id===byId('model').value);return{binding,source,view,pair,scan,model}}
function patchChoices(){let{binding,pair}=current(),select=byId('model');select.replaceChildren();let models=data.evidence.conditional_roof_patches.filter(m=>m.source_level_binding_id===binding.id&&m.source_pair_id===pair?.id);if(!models.length)option(select,'','No conditional patch for this source gable');for(let m of models)option(select,m.id,`Ink ${m.source_ink_threshold} · rail sign ${m.image_left_to_native_rail_orientation} · ${m.id.slice(0,10)}`);draw()}
function levelChoices(){let{binding,view}=current(),select=byId('pair');select.replaceChildren();let pairs=view?.variants.flatMap(s=>s.gable_intersections)||[];if(!pairs.length)option(select,'','No supported face-on roof context');for(let p of pairs)option(select,p.id,`${p.id.slice(0,10)} · ridge ${p.inferred_ridge_pixel.map(v=>v.toFixed(1)).join(', ')}`);let first=data.evidence.conditional_roof_patches.find(m=>m.source_level_binding_id===binding.id);if(first)select.value=first.source_pair_id;patchChoices()}
function meshDraw(model){let svg=byId('mesh');svg.replaceChildren();byId('obj').disabled=!model;if(!model){byId('mesh-status').textContent='No conditional patch for this selected source combination. The failed or unsupported source evidence remains reviewable.';byId('heights').textContent='';return}let yaw=Number(byId('yaw').value)*Math.PI/180,vertices=model.mesh.vertices,project=p=>[(p[0]*Math.cos(yaw)-p[1]*Math.sin(yaw))*35,(p[0]*Math.sin(yaw)+p[1]*Math.cos(yaw))*18-p[2]*35],points=vertices.map(project),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);svg.setAttribute('viewBox',[Math.min(...xs)-30,Math.min(...ys)-30,Math.max(...xs)-Math.min(...xs)+60,Math.max(...ys)-Math.min(...ys)+60].join(' '));let faces=model.mesh.triangles.map((face,i)=>({face,i,depth:face.reduce((s,j)=>s+vertices[j][0]*Math.sin(yaw)+vertices[j][1]*Math.cos(yaw),0)})).sort((a,b)=>a.depth-b.depth);for(let{face,i}of faces)node('polygon',{points:face.map(j=>points[j].join(',')).join(' '),fill:i<2?'#4e96b8':'#2e6788',stroke:'#153f57','stroke-width':1,class:'mesh-face','data-face-index':i,'data-vertex-indices':face.join(',')},svg);for(let[i,p]of points.entries())node('circle',{cx:p[0],cy:p[1],r:2.2,fill:'#b98316',class:'mesh-vertex','data-index':i},svg);byId('mesh-status').textContent='Six original-plan vertices / four triangles. Continuous surfaces are assumed. Mesh ends at original source cap witnesses; whole rail tails remain unmeshed. Local nominal metres, Z up; no geographic placement.';byId('heights').textContent=`Relative to ${model.source_level_label} (${model.source_level_value_m_candidate}): ridge ${model.mesh.ridge_height_above_printed_level_nominal_m.toFixed(4)} m; separate fascia-end heights ${model.mesh.eave_endcap_heights_above_printed_level_nominal_m.map(v=>v.toFixed(4)).join(' / ')} m. Physical eave roles remain unverified.`}
function draw(){let s=current();state=s;let{binding,source,view,pair,scan,model}=s,im=packed.images[source.view_id],svg=byId('source');svg.replaceChildren();let levelPage=data.evidence.level_pages.find(p=>p.marker_bindings.some(b=>b.id===binding.id)),legacy=levelPage.legacy_marker_review.records.find(m=>m.id===binding.legacy_marker_id),receipt=data.receipts[source.view_id],displayToPixel=receipt.display_to_pixel,convert=p=>[p[0]*displayToPixel[0]+p[1]*displayToPixel[2]+displayToPixel[4],p[0]*displayToPixel[1]+p[1]*displayToPixel[3]+displayToPixel[5]],box=b=>{let a=convert([b[0],b[1]]),z=convert([b[2],b[3]]);return[a[0],a[1],z[0]-a[0],z[1]-a[1]]},bounds=[0,0,...im.size];if(!byId('full').checked&&pair){let c=box(binding.circle_bbox_display_points),x0=Math.max(0,Math.min(pair.inferred_ridge_pixel[0]-240,c[0])-35),y0=Math.max(0,pair.inferred_ridge_pixel[1]-65);bounds=[x0,y0,Math.min(im.size[0],Math.max(pair.inferred_ridge_pixel[0]+240,c[0]+c[2])+40)-x0,Math.min(im.size[1],Math.max(pair.inferred_ridge_pixel[1]+240,c[1]+c[3])+45)-y0]}svg.setAttribute('viewBox',bounds.join(' '));node('image',{href:im.png,x:0,y:0,width:im.size[0],height:im.size[1]},svg);byId('caption').textContent=im.caption;
for(let line of binding.source_datum_line_candidates)node('polyline',{points:line.display_endpoints.map(p=>convert(p).join(',')).join(' '),fill:'none',stroke:'#1c805c','stroke-width':1.5,class:'source-level-leader'},svg);let circle=box(binding.circle_bbox_display_points);node('rect',{x:circle[0],y:circle[1],width:circle[2],height:circle[3],fill:'none',stroke:'#1c805c','stroke-width':1.5,class:'source-level-marker'},svg);for(let candidate of binding.label_candidates){if(candidate.source_fragment_ids){let matrix=receipt.page_to_pixel;for(let id of candidate.source_fragment_ids){let f=Object.values(levelPage.fragments).flat().find(f=>f.id===id),b=f.bbox_page_points,points=[[b[0],b[1]],[b[2],b[1]],[b[2],b[3]],[b[0],b[3]]].map(p=>[p[0]*matrix[0]+p[1]*matrix[2]+matrix[4],p[0]*matrix[1]+p[1]*matrix[3]+matrix[5]]),xs=points.map(p=>p[0]),ys=points.map(p=>p[1]);node('rect',{x:Math.min(...xs),y:Math.min(...ys),width:Math.max(...xs)-Math.min(...xs),height:Math.max(...ys)-Math.min(...ys),fill:'none',stroke:'#1c805c','stroke-width':1,class:'source-split-fragment-bounds','data-fragment-id':id},svg)}}else{let b=box(candidate.bbox_display_points);node('rect',{x:b[0],y:b[1],width:b[2],height:b[3],fill:'none',stroke:'#1c805c','stroke-width':1,class:'source-level-label-bounds'},svg)}}
if(pair){for(let[key,color]of[['left_line_id','#236ca9'],['right_line_id','#bd8700']]){let line=scan.lines.find(l=>l.id===pair[key]);node('polyline',{points:line.source_x_interval.map(x=>[x,line.slope*x+line.intercept].join(',')).join(' '),fill:'none',stroke:color,'stroke-width':1.4,class:'source-slope-fit','data-line-id':line.id},svg);if(byId('pixels').checked)for(let role of['fit','check']){let points=line.source_pixels.filter(p=>p.role===role);node('path',{d:points.map(p=>`M${p.x} ${p.y}l0 0`).join(' '),stroke:role==='fit'?color:'#d2513c','stroke-linecap':'round','stroke-width':1.7,class:'source-slope-pixels','data-line-id':line.id,'data-role':role},svg)}}node('circle',{cx:pair.inferred_ridge_pixel[0],cy:pair.inferred_ridge_pixel[1],r:3,fill:'#c33028',class:'inferred-ridge'},svg)}if(model){let c=data.evidence.endcap_checks.find(c=>c.id===model.source_endcap_check_id);for(let id of c.source_fascia_column_ids){let cap=scan.source_fascia_columns.find(p=>p.id===id);if(byId('pixels').checked)node('path',{d:cap.source_pixels.map(p=>`M${p.x} ${p.y}l0 0`).join(' '),stroke:'#ae2c92','stroke-linecap':'round','stroke-width':2,class:'source-fascia-pixels','data-cap-id':id},svg)}}meshDraw(model);
let heightChecks=pair?data.evidence.inter_sheet_height_checks.filter(c=>c.source_pair_id===pair.id&&c.source_level_binding_id===binding.id):[],agree=heightChecks.filter(c=>c.status==='conditional_inter_sheet_ridge_height_agrees').length;byId('status').textContent=`${binding.label.level_label_candidate}: ${binding.label.value_m_candidate} · ${binding.status.replaceAll('_',' ')}. Previous marker result: ${binding.legacy_marker_status.replaceAll('_',' ')}. ${pair?`${agree}/${heightChecks.length} retained inter-sheet height diagnostics agree for this gable.`:'No supported roof proposal for this source view.'} Printed levels do not establish a physical floor or survey datum.`;byId('marker').textContent=JSON.stringify({binding,legacy,split_pairs:levelPage.split_pairs,fragments:levelPage.fragments},null,2);byId('height-checks').textContent=heightChecks.map(c=>`${c.old_source_pair_id.slice(0,12)} | ${c.signed_source_ridge_height_difference_nominal_m.toFixed(5)} nominal m | ${c.status}`).join('\n');byId('height-checks').style.whiteSpace='pre-wrap';byId('ends').textContent=JSON.stringify(pair?data.evidence.endcap_checks.filter(c=>c.source_pair_id===pair.id):[],null,2);byId('thresholds').textContent=JSON.stringify(model?data.evidence.threshold_checks.filter(c=>c.source_model_ids.includes(model.id)):[],null,2)}
async function start(){raw=await new Response(new Blob([Uint8Array.from(atob(packed.gzip_json),c=>c.charCodeAt(0))]).stream().pipeThrough(new DecompressionStream('gzip'))).text();let evidence=JSON.parse(raw);data={evidence,bindings:evidence.level_pages.flatMap(p=>p.marker_bindings).filter(b=>b.status==='unverified_source_level_marker_binding'),receipts:packed.receipts};for(let[k,v]of[['bound source markers',evidence.counts.source_marker_bindings],['relative level checks',evidence.counts.relative_level_checks],['conditional cap patches',evidence.counts.conditional_roof_patches],['cross-threshold checks',evidence.counts.threshold_checks]]){let div=document.createElement('div');div.className='metric';let b=document.createElement('b');b.textContent=v;div.append(b,document.createTextNode(k));byId('metrics').append(div)}for(let b of data.bindings)option(byId('level'),b.id,`${b.view_key_candidate.join('/')} · ${b.label.level_label_candidate} ${b.label.value_m_candidate}`);for(let page of evidence.level_pages)for(let c of page.relative_checks){let tr=document.createElement('tr');for(let value of[c.view_key_candidate.join('/'),c.printed_difference_m_candidate.toFixed(5)+' m',c.nominal_source_difference_m.toFixed(5)+' m',c.difference_residual_nominal_m.toFixed(6)+' m',c.status.replaceAll('_',' ')]){let td=document.createElement('td');td.textContent=value;tr.append(td)}byId('levels').append(tr)}let first=evidence.conditional_roof_patches.find(m=>data.bindings.find(b=>b.id===m.source_level_binding_id)?.label.split_pair_id);if(first)byId('level').value=first.source_level_binding_id;byId('level').addEventListener('change',levelChoices);byId('pair').addEventListener('change',patchChoices);for(let id of['model','full','pixels'])byId(id).addEventListener('change',draw);byId('yaw').addEventListener('input',()=>meshDraw(current().model));byId('download').addEventListener('click',()=>save(raw,'preshow-level-geometry.json','application/json'));byId('obj').addEventListener('click',()=>{let model=current().model;if(model)save(Uint8Array.from(atob(packed.obj_files[model.id]),c=>c.charCodeAt(0)),model.id+'.obj','text/plain')});byId('hash').textContent='Evidence SHA-256: '+packed.review_sha256;levelChoices();document.body.dataset.ready='true'}start().catch(e=>{byId('status').textContent=String(e);throw e});
</script></html>'''
    # Compose reversible pixel/display maps from pinned source crop receipts and original page rotations.
    payload['receipts']={}
    for page in parent['additional_pages']:
        original=additional_pdfs/(page['document_sha256']+'.pdf')
        if file_hash(original)!=page['document_sha256']:raise ValueError('Original source PDF changed')
        with pymupdf.open(original) as doc:
            source_page=doc[page['page']-1];page_native=native_inverse(source_page)
            native_display=~page_native*source_page.rotation_matrix
        for view in page['view_candidates']['views']:
            source=next(s for s in parent['rendered_views'] if s['view_id']==view['id']);r=json.loads((references/source['receipt']).read_text())
            native_pixel=~pymupdf.Matrix(r['pixel_edge_to_pdf_native_matrix'])
            payload['receipts'][view['id']]={'display_to_pixel':list(~native_display*native_pixel),
                'page_to_pixel':list(page_native*native_pixel)}
    html=html.replace('PAYLOAD',json.dumps(payload,separators=(',',':')).replace('<','\u003c'))
    output.parent.mkdir(parents=True,exist_ok=True);output.write_text(html)
    return {'output':str(output),'bytes':output.stat().st_size,'source_images':len(payload['images'])}


if __name__=='__main__':
    p=argparse.ArgumentParser(description=__doc__)
    for name in ('evidence','references','objs','additional-pdfs','output'):p.add_argument('--'+name,type=Path,required=True)
    print(json.dumps(render(**vars(p.parse_args()))))
